-- Generated by Murakumo: load tpch_erp.partsupp (append), without Murakumo. Run it from the project folder.

-- The files under landing/tpch_erp/partsupp/ that were not loaded before.
create or replace temp table new_rows as
select cast(ps_partkey as BIGINT) as ps_partkey, cast(ps_suppkey as BIGINT) as ps_suppkey, cast(ps_availqty as INTEGER) as ps_availqty, cast(ps_supplycost as DECIMAL(15,2)) as ps_supplycost, cast(ps_comment as VARCHAR) as ps_comment, filename
from read_json('landing/tpch_erp/partsupp/partsupp_*.jsonl', format = 'newline_delimited', filename = true, columns = {'ps_partkey': 'BIGINT', 'ps_suppkey': 'BIGINT', 'ps_availqty': 'INTEGER', 'ps_supplycost': 'DECIMAL(15,2)', 'ps_comment': 'VARCHAR'})
where parse_filename(filename) not in (select parse_filename(path) from audit.loaded_files where table_name = 'partsupp');
-- Append: the new files' rows are added.
insert into raw_tpch_erp.partsupp (ps_partkey, ps_suppkey, ps_availqty, ps_supplycost, ps_comment, _ingested_at, _batch_id)
select ps_partkey, ps_suppkey, ps_availqty, ps_supplycost, ps_comment, now(), parse_filename(filename) from new_rows;
-- Remember the files, so the next run skips them.
insert into audit.loaded_files (table_name, path, size, sha256, rows_ingested, batch_id, loaded_at)
select 'partsupp', filename, null, null, count(*), parse_filename(filename), now()
from new_rows group by filename;
drop table new_rows;
